package binding

import (
	"bytes"
	"mime/multipart"
	"net/http"
	"testing"
)

func TestScratchNonMandatoryFile(t *testing.T) {
	var body bytes.Buffer
	mw := multipart.NewWriter(&body)
	_ = mw.WriteField("name", "test-name")
	_ = mw.WriteField("email", "test-email")
	// file part with empty filename, as browsers send when no file is selected
	_, err := mw.CreateFormFile("file", "")
	if err != nil {
		t.Fatal(err)
	}
	_ = mw.Close()

	req, _ := http.NewRequest("POST", "/", &body)
	req.Header.Set("Content-Type", MIMEMultipartPOSTForm+"; boundary="+mw.Boundary())

	var s struct {
		Name  string                `form:"name" binding:"required"`
		Email string                `form:"email" binding:"required"`
		File  *multipart.FileHeader `form:"file"`
	}
	if err := FormMultipart.Bind(req, &s); err != nil {
		t.Fatalf("expected no error, got: %v", err)
	}
	if s.Name != "test-name" || s.Email != "test-email" {
		t.Fatalf("fields not bound: %+v", s)
	}
	if s.File == nil || s.File.Filename != "" {
		t.Fatalf("expected empty non-nil FileHeader, got %+v", s.File)
	}
	t.Logf("OK: File=%+v", *s.File)
}

